if (input.method) {
  method = input.method.toUpperCase();
} else if (input.headers && input.headers['x-http-method']) {
  method = input.headers['x-http-method'].toUpperCase();
} else if (input.body && Object.keys(input.body).length > 0) {
  method = 'POST';
}

return {
  json: {
    ...input,
    httpMethod: method
  }
};

