}

const weightDiff = Math.abs(data.goalValue - data.weight);
const weightDiffPercent = (weightDiff / data.weight) * 100;

if (weightDiffPercent > 30) {
  errors.push('目标体重与当前体重差异过大（超过30%），请确认目标是否合理');
}

