const data = $input.item.json.data;
const { age, gender, height, weight, experience, dailyTime } = data;

// 计算BMR (Harris-Benedict公式)
let bmr;
const heightInMeters = height / 100;

if (gender === '男') {
  bmr = 88.362 + (13.397 * weight) + (4.799 * height) - (5.677 * age);
} else {
  bmr = 447.593 + (9.247 * weight) + (3.098 * height) - (4.330 * age);
}

// 根据运动经验确定活动系数
let activityFactor;
if (experience === '新手') {
  activityFactor = dailyTime < 30 ? 1.2 : 1.375;
} else if (experience === '有经验') {
  activityFactor = dailyTime < 30 ? 1.375 : dailyTime < 60 ? 1.55 : 1.725;
} else {
  activityFactor = dailyTime < 60 ? 1.55 : 1.9;
}

// 计算TDEE
const tdee = bmr * activityFactor;

// 计算目标热量
const { goalType, goalValue, goalTime, weight: currentWeight } = data;
const weightDiff = goalValue - currentWeight;
const weeklyWeightChange = Math.abs(weightDiff) / goalTime;

let targetCalories, calorieDeficitOrSurplus;

if (goalType === '减肥') {
  const targetWeeklyLoss = Math.min(weeklyWeightChange, 1);
  calorieDeficitOrSurplus = -(targetWeeklyLoss * 7700) / 7;
  targetCalories = tdee + calorieDeficitOrSurplus;
  targetCalories = Math.max(targetCalories, bmr * 0.8);
} else if (goalType === '增肌') {
  const targetWeeklyGain = Math.min(weeklyWeightChange, 0.5);
  calorieDeficitOrSurplus = (targetWeeklyGain * 7700) / 7;
  targetCalories = tdee + calorieDeficitOrSurplus;
} else {
  targetCalories = tdee;
  calorieDeficitOrSurplus = 0;
}

// 计算营养素分配
let protein, carbs, fat;

if (goalType === '增肌') {
  protein = weight * 2.0;
} else if (goalType === '减肥') {
  protein = weight * 1.4;
} else {
  protein = weight * 1.0;
}

const proteinCalories = protein * 4;
const remainingCalories = targetCalories - proteinCalories;

const fatCalories = targetCalories * 0.25;
fat = fatCalories / 9;

const carbCalories = remainingCalories - fatCalories;
carbs = carbCalories / 4;

// BMI评估
const bmi = weight / (heightInMeters * heightInMeters);
let bmiStatus;
if (bmi < 18.5) bmiStatus = '偏瘦';
else if (bmi < 24) bmiStatus = '正常';
else if (bmi < 28) bmiStatus = '偏胖';
else bmiStatus = '肥胖';

return {
  json: {
    profile: data,
    calculations: {
      bmr: Math.round(bmr),
      tdee: Math.round(tdee),
      activityFactor: activityFactor,
      targetCalories: Math.round(targetCalories),
      calorieDeficitOrSurplus: Math.round(calorieDeficitOrSurplus),
      bmi: parseFloat(bmi.toFixed(1)),
      bmiStatus: bmiStatus,
      nutrients: {
        protein: Math.round(protein),
        carbs: Math.round(carbs),
        fat: Math.round(fat)
      },
      goalAnalysis: {
        goalType: goalType,
        weeklyChange: parseFloat(weeklyWeightChange.toFixed(2)),
        totalWeeks: goalTime
      }
    }
  }
};

